      auto r5 = __builtin_aiev2_I512_I1024_ACC1024_acc32_negmac_conf(a2, d2, m2, r0, conf);
      auto r6 = __builtin_aiev2_I512_I1024_ACC1024_acc32_negmsc_conf(a2, d2, m2, r0, conf);
      auto r7 = __builtin_aiev2_I512_I1024_ACC1024_ACC1024_acc32_addmac_conf(a2, d2, m2, r0, r1, conf);
      auto r8 = __builtin_aiev2_I512_I1024_ACC1024_ACC1024_acc32_addmsc_conf(a2, d2, m2, r0, r1, conf);
